import { createTokenPair, toUserId, verifyAccessToken } from "@zudojs/auth";

const config = { accessSecret: "a".repeat(32), refreshSecret: "r".repeat(32) };
const real = createTokenPair(toUserId("u-ada"), config, { roles: ["user"] });
const [header, payload, signature] = real.accessToken.split(".");
const encode = (value) => Buffer.from(JSON.stringify(value)).toString("base64url");
const claims = JSON.parse(Buffer.from(payload, "base64url").toString());
const admin = encode({ ...claims, roles: ["admin"] });

const attempts = [
  `${header}.${admin}.${signature}`,
  `${encode({ alg: "none", typ: "JWT" })}.${admin}.${signature}`,
  real.refreshToken,
];
for (const token of attempts) {
  const result = verifyAccessToken(token, config);
  console.log(result.valid, result.error);
}

