function bearerToken(header) {
  if (typeof header !== "string") return null;
  const match = /^Bearer ([^\s]+)$/.exec(header);
  return match ? match[1] : null;
}

console.log(bearerToken("Bearer abc.def.ghi"));
console.log(bearerToken(undefined), bearerToken("Basic dXNlcg=="), bearerToken("Bearer "), bearerToken("Bearer a b"));

