questions.solution:
function createLockout(max) {
  const failures = new Map();
  return function attempt(email, passwordOk) {
    const key = email.trim().toLowerCase();
    const count = failures.get(key) ?? 0;
    if (count >= max) return "locked";
    if (passwordOk) {
      failures.delete(key);
      return "ok";
    }
    failures.set(key, count + 1);
    return "invalid";
  };
}

const attempt = createLockout(3);
