questions.solution:
const tasks = [{ id: 1, ownerId: "u-linus", title: "Fix the bike" }];

function listTasks(user) {
  return tasks.filter((task) => task.ownerId === user.sub);
}

function createTask(user, body) {
  const task = { id: tasks.length + 1, ownerId: user.sub, title: body.title.trim() };
  tasks.push(task);
  return task;
}

